# 代码行数统计（按 crate）
$crates = @(
    @{Name="vn-runtime"; Path="libs/vn-runtime/src"},
    @{Name="ring-resources"; Path="libs/ring-resources/src"},
    @{Name="ring-audio"; Path="libs/ring-audio/src"},
    @{Name="ring-render"; Path="libs/ring-render/src"},
    @{Name="ring-player"; Path="apps/ring-player/src"},
    @{Name="xtask"; Path="tools/xtask/src"},
    @{Name="asset-packer"; Path="tools/asset-packer/src"},
    @{Name="ring-lsp"; Path="tools/ring-lsp/src"}
)
foreach ($c in $crates) {
    $files = Get-ChildItem -Path $c.Path -Recurse -Filter "*.rs" -ErrorAction SilentlyContinue
    $total = 0
    foreach ($f in $files) { $total += (Get-Content $f.FullName | Measure-Object -Line).Lines }
    $fileCount = if ($files) { $files.Count } else { 0 }
    Write-Output "$($c.Name): $fileCount files, $total lines"
}

# 测试统计（按 crate 统计 #[test] 数量）
$crates = @(
    @{Name="vn-runtime"; Path="libs/vn-runtime/src"},
    @{Name="ring-resources"; Path="libs/ring-resources/src"},
    @{Name="ring-audio"; Path="libs/ring-audio/src"},
    @{Name="ring-render"; Path="libs/ring-render/src"},
    @{Name="ring-player"; Path="apps/ring-player/src"},
    @{Name="ring-lsp"; Path="tools/ring-lsp/src"},
    @{Name="asset-packer"; Path="tools/asset-packer/src"}
)
foreach ($c in $crates) {
    $files = Get-ChildItem -Path $c.Path -Recurse -Filter "*.rs" -ErrorAction SilentlyContinue
    $testCount = 0
    foreach ($f in $files) {
        $matches = Select-String -Path $f.FullName -Pattern '#\[test\]' -AllMatches
        if ($matches) { $testCount += ($matches | ForEach-Object { $_.Matches.Count } | Measure-Object -Sum).Sum }
    }
    Write-Output "$($c.Name): $testCount tests"
}

