# 检查文档覆盖率 - pub 项是否有 doc comment
# 统计 libs/ 下 pub fn/struct/enum 无 doc comment 的情况
$files = Get-ChildItem -Path libs -Recurse -Filter "*.rs" | Where-Object { $_.FullName -notmatch "tests?" }
$pubItems = 0
$docItems = 0
foreach ($f in $files) {
    $lines = Get-Content $f.FullName
    for ($i = 0; $i -lt $lines.Length; $i++) {
        if ($lines[$i] -match '^\s*pub\s+(fn|struct|enum|trait|type)\s+') {
            $pubItems++
            # check if previous non-empty line is a doc comment
            $j = $i - 1
            while ($j -ge 0 -and $lines[$j] -match '^\s*$') { $j-- }
