[package]
name = "ring-player"
version = "0.1.0"
edition = "2024"
license = "MIT"

[lints]
workspace = true

[features]
default = ["desktop"]
desktop = ["dioxus/desktop", "dep:axum", "tokio/net"]
web = ["dioxus/web", "dep:js-sys"]

[dependencies]
dioxus = { version = "0.7", default-features = false, features = ["minimal", "document"] }
tokio = { version = "1", features = ["rt", "time", "macros"] }
axum = { version = "0.8", default-features = false, features = ["json", "tokio", "http1"], optional = true }

# ── 后端核心 ──
vn-runtime = { workspace = true }
ring-resources = { workspace = true }
ring-audio = { workspace = true }
ring-render = { workspace = true }
serde = { workspace = true }
serde_json = { workspace = true }
thiserror = { workspace = true }
tracing = "0.1"
tracing-subscriber = "0.3"
zip = { workspace = true, features = ["deflate"] }
base64 = "0.22"

# ── WASM ──
js-sys = { version = "0.3", optional = true }

input.command:
# RFC 状态检查
Get-ChildItem -Path RFCs -Filter "*.md" -ErrorAction SilentlyContinue | Where-Object { $_.Name -ne "README.md" } | ForEach-Object { "$($_.Directory.Name)/$($_.Name)" }
Write-Output "---"
Get-ChildItem -Path RFCs/Archived -Filter "*.md" -ErrorAction SilentlyContinue | ForEach-Object { "Archived/$($_.Name)" }

# 测试覆盖率 - 检查最近的覆盖率报告是否存在
if (Test-Path "target/llvm-cov/html/index.html") {
    $date = (Get-Item "target/llvm-cov/html/index.html").LastWriteTime
    Write-Output "Last coverage report: $date"
} else {
    Write-Output "No coverage report found"
}

# 检查编译器版本
rustc --version
cargo --version

# 全面检查 ring-player 页面/路由是否有对应测试
Get-ChildItem -Path apps/ring-player/src -Recurse -Filter "*.rs" | Where-Object { $_.Name -ne "mod.rs" -and $_.Name -notmatch "test" } | ForEach-Object {
    $hasTests = Select-String -Path $_.FullName -Pattern '#\[cfg\(test\)\]' -Quiet
    $relPath = $_.FullName -replace [regex]::Escape("$PWD\"), ''
    if (-not $hasTests) { Write-Output "NO TEST: $relPath" }
} | Sort-Object

# ring-player 中有测试的文件
Get-ChildItem -Path apps/ring-player/src -Recurse -Filter "*.rs" | Where-Object { $_.Name -ne "mod.rs" } | ForEach-Object {
    $hasTests = Select-String -Path $_.FullName -Pattern '#\[cfg\(test\)\]' -Quiet
    $relPath = $_.FullName -replace [regex]::Escape("$PWD\"), ''
    if ($hasTests) { Write-Output "HAS TEST: $relPath" }
} | Sort-Object

# libs/ 中无测试的非 mod.rs 文件
Get-ChildItem -Path libs -Recurse -Filter "*.rs" | Where-Object { $_.Name -ne "mod.rs" -and $_.Name -notmatch "test" -and $_.FullName -notmatch "\\tests\\" } | ForEach-Object {
    $hasTests = Select-String -Path $_.FullName -Pattern '#\[cfg\(test\)\]' -Quiet
    $relPath = $_.FullName -replace [regex]::Escape("$PWD\"), ''
    if (-not $hasTests) { Write-Output "$relPath" }
} | Sort-Object

# 检查 ring-player 的测试覆盖 - state/mod.rs 有测试吗
$stateTests = Select-String -Path "apps/ring-player/src/state/tests.rs" -Pattern '#\[test\]' -ErrorAction SilentlyContinue
if ($stateTests) { Write-Output "state/tests.rs has $($stateTests.Count) test functions" }

# state mod.rs 引用 tests
Select-String -Path "apps/ring-player/src/state/mod.rs" -Pattern "tests" -ErrorAction SilentlyContinue | ForEach-Object { $_.Line.Trim() }

# ring-player 有 state/tests.rs (12 tests) + save_manager tests + init tests
# 统计这些测试覆盖了哪些 state 子模块
Select-String -Path "apps/ring-player/src/state/tests.rs" -Pattern 'fn test_\w+' | ForEach-Object { $_.Line.Trim() }

