#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Write as _;

    fn create_test_zip(dir: &std::path::Path) -> std::path::PathBuf {
        let zip_path = dir.join("test.zip");
        let file = std::fs::File::create(&zip_path).unwrap();
        let mut writer = zip::ZipWriter::new(file);
        let opts = zip::write::SimpleFileOptions::default();
        writer.start_file("a.txt", opts).unwrap();
        writer.write_all(b"hello").unwrap();
        writer.start_file("b.txt", opts).unwrap();
        writer.write_all(b"world").unwrap();
        writer.finish().unwrap();
        zip_path
    }

    #[test]
    fn verify_zip_valid() {
        let tmp = std::env::temp_dir().join("asset_packer_test_verify");
        let _ = std::fs::remove_dir_all(&tmp);
        std::fs::create_dir_all(&tmp).unwrap();
        let zip_path = create_test_zip(&tmp);
        // 无 input 参数时仅检查 ZIP 可读性
        assert!(verify_zip(&zip_path, None).is_ok());
        let _ = std::fs::remove_dir_all(&tmp);
    }

    #[test]
    fn verify_zip_with_matching_source() {
        let tmp = std::env::temp_dir().join("asset_packer_test_verify_match");
        let _ = std::fs::remove_dir_all(&tmp);
        let src = tmp.join("src");
        std::fs::create_dir_all(&src).unwrap();
        std::fs::write(src.join("a.txt"), "hello").unwrap();
        std::fs::write(src.join("b.txt"), "world").unwrap();
        let zip_path = create_test_zip(&tmp);
        assert!(verify_zip(&zip_path, Some(&src)).is_ok());
        let _ = std::fs::remove_dir_all(&tmp);
    }

    #[test]
    fn verify_zip_detects_content_mismatch() {
        let tmp = std::env::temp_dir().join("asset_packer_test_verify_mismatch");
        let _ = std::fs::remove_dir_all(&tmp);
        let src = tmp.join("src");
        std::fs::create_dir_all(&src).unwrap();
        std::fs::write(src.join("a.txt"), "WRONG").unwrap();
        std::fs::write(src.join("b.txt"), "world").unwrap();
        let zip_path = create_test_zip(&tmp);
        assert!(verify_zip(&zip_path, Some(&src)).is_err());
        let _ = std::fs::remove_dir_all(&tmp);
    }
}
