#[cfg(test)]
mod tests {
    use super::*;
    use std::io::Read as _;

    #[test]
    fn pack_directory_round_trip() {
        let tmp = std::env::temp_dir().join("asset_packer_test_pack");
        let _ = std::fs::remove_dir_all(&tmp);
        std::fs::create_dir_all(tmp.join("sub")).unwrap();
        std::fs::write(tmp.join("hello.txt"), "world").unwrap();
        std::fs::write(tmp.join("sub/nested.txt"), "deep").unwrap();

        let zip_path = tmp.join("out.zip");
        pack_directory(&tmp, &zip_path).unwrap();

        // 验证 ZIP 包含正确文件
        let file = std::fs::File::open(&zip_path).unwrap();
        let mut archive = zip::ZipArchive::new(file).unwrap();
        assert_eq!(archive.len(), 2);

        let mut content = String::new();
        archive
            .by_name("hello.txt")
            .unwrap()
            .read_to_string(&mut content)
            .unwrap();
        assert_eq!(content, "world");

        content.clear();
        archive
            .by_name("sub/nested.txt")
            .unwrap()
            .read_to_string(&mut content)
            .unwrap();
        assert_eq!(content, "deep");

        let _ = std::fs::remove_dir_all(&tmp);
    }

    #[test]
    fn pack_empty_directory() {
        let tmp = std::env::temp_dir().join("asset_packer_test_empty");
        let _ = std::fs::remove_dir_all(&tmp);
        std::fs::create_dir_all(&tmp).unwrap();

        let zip_path = tmp.join("empty.zip");
        pack_directory(&tmp, &zip_path).unwrap();

        let file = std::fs::File::open(&zip_path).unwrap();
        let archive = zip::ZipArchive::new(file).unwrap();
        assert_eq!(archive.len(), 0);

        let _ = std::fs::remove_dir_all(&tmp);
    }
}
